      brevoApiKey: 'test-api-key',
      listId: 123,
      updateEnabled: true,
    }
    calls = []
  })

  function makeFetch(response: Response) {
    const { fetch, calls: recordedCalls } = fakeFetch(() => response)
    calls.push(...recordedCalls)
    return fetch
  }

  it('creates contact with email, first name, last name and subscribes to list', async () => {
    const fetch = makeFetch(jsonResponse({ id: 789 }, 201))
    const payload: TypeformWebhookPayload = {
      event_id: 'evt1',
      event_type: 'form_response',
      form_response: {
        form_id: 'f1',
        token: 't1',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'test@example.com', field: { id: 'e1', type: 'email' } },
          { type: 'text', text: 'John', field: { id: 'fn1', type: 'short_text' } },
          { type: 'text', text: 'Doe', field: { id: 'ln1', type: 'short_text' } },
        ],
      },
    }
    const result = await handle(payload, { ...baseConfig, fetch })
    expect(result.contactId).toBe(789)
    expect(calls).toHaveLength(1)
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://api.brevo.com/v3/contacts')
    expect(calls[0].json).toEqual({
      email: 'test@example.com',
      attributes: { FNAME: 'John', LNAME: 'Doe' },
      listIds: [123],
      updateEnabled: true,
    })
    expect(calls[0].headers.get('api-key')).toBe('test-api-key')
  })

  it('includes custom attributes from field.ref', async () => {
    const fetch = makeFetch(jsonResponse({ id: 999 }, 201))
